"""Original compiler and runtime glossary for Go chapters 46–57."""

GLOSSARY = [
    ("Лексема Go", "Единица текста, распознанная лексическим анализатором: имя, ключевое слово, литерал или знак операции. Последовательность символов внутри строки либо комментария имеет другой смысл, поэтому текстовый поиск знака операции не заменяет разбор программы."),
    ("Парсер Go", "Часть обработки исходника, которая проверяет грамматическую организацию лексем и строит синтаксическое дерево. Успешный разбор показывает допустимую форму, но ещё не доказывает совместимость типов и правильность алгоритма."),
    ("AST Go", "Дерево синтаксиса с узлами объявлений, выражений и операторов, сохраняющее их вложенность и позиции. Внутренний компиляторный syntax и публичный go/ast являются разными представлениями, поэтому дамп одного нельзя выдавать за точную структуру другого."),
    ("Types2", "Внутренняя система проверки типов компилятора Go, работающая с его синтаксическим деревом. Она разрешает определения, использования, ограничения и подстановки; результат нужен последующим преобразованиям, а не только сообщениям об ошибках."),
    ("Noder", "Часть компилятора, связывающая проверенный синтаксис и типы с дальнейшим внутренним представлением программы. В Go 1.27.3 она участвует в Unified IR, импорте, экспорте и подготовке тел функций."),
    ("Unified IR", "Согласованное сериализованное представление проверенного кода, используемое компилятором при передаче сведений и создании внутренних узлов. Оно помогает обслуживать импорт, встраивание и обобщённые определения; его формат не является стабильным внешним интерфейсом между любыми версиями Go."),
    ("Export data Go", "Сведения скомпилированного пакета, необходимые последующим компиляциям: типы, некоторые тела функций и сводки анализа параметров. Чтение этих данных не запускает init пакета и не равно исполнению импортированной библиотеки."),
    ("Задача инициализации Go", "Подготовленное компилятором и связывателем описание необходимой пакетной инициализации. Оно помогает runtime выполнить зависимости и функции init в требуемом порядке; статически размещённые данные не обязаны иметь отдельный вычисляющий вызов."),
    ("Множество типов", "Совокупность типов, описанная ограничением параметра типа. Она определяет, какие операции допустимы в обобщённом теле, и отличается от конкретного интерфейсного значения, существующего во время исполнения."),
    ("Параметр типа Go", "Обозначение типа, который будет выбран при конкретизации обобщённого определения. Тело функции обязано быть допустимым для всех разрешённых ограничением вариантов, а не только для первого встреченного вызова."),
    ("Ограничение типа Go", "Статический договор о допустимых типовых аргументах и доступных операциях. Например, ~int включает типы с соответствующим базовым типом, но any не разрешает автоматически складывать произвольные значения."),
    ("Конкретизация Go", "Подстановка определённых типов в обобщённое определение с проверкой их соответствия ограничению. Это стадия компиляции, а не поиск операции по строковому имени типа при каждом вызове."),
    ("Go shape", "Внутренняя форма компилятора, позволяющая разделять реализацию между некоторыми совместимыми типовыми подстановками. Группировка зависит от версии, операций и представления, поэтому одинаковый размер значений сам по себе не обещает одно общее тело."),
    ("Словарь конкретизации Go", "Сгенерированные сведения, необходимые общей форме обобщённой функции для конкретных типов и связанных операций. Это не обычная map со строковыми ключами; отдельно существуют структуры самого компилятора и данные создаваемой программы."),
    ("Упаковка в интерфейс", "Создание интерфейсного представления с динамическим типом и доступом к данным конкретного значения. Такая упаковка не всегда означает новое кучевое выделение: результат зависит от времени жизни и оптимизаций."),
    ("Itab", "Внутренние сведения о соответствии конкретного типа интерфейсу с методами и необходимых реализациях вызовов. Они помогают выполнить динамический метод, но не являются полным описанием всех возможных интерфейсных преобразований."),
    ("Девиртуализация Go", "Замена косвенного вызова известной прямой реализацией, когда для этого достаточно доказательств или подходящего профильного преобразования. Она может открыть возможность встраивания, но не происходит обязательно у каждого интерфейсного вызова."),
    ("Встраивание функции Go", "Преобразование подходящего вызова в реализацию тела с корректной подстановкой аргументов и результатов. Кроме устранения границы оно раскрывает константы и время жизни, но может увеличивать код и стоимость компиляции."),
    ("Бюджет встраивания", "Эвристическое ограничение, помогающее компилятору выбирать, какие тела и вызовы разумно раскрывать. Сообщение о возможности встраивания не доказывает, что оно фактически выполнено в каждом месте вызова."),
    ("Escape analysis Go", "Статическое исследование движения значений и адресов для безопасного выбора времени и места хранения. Слово escape здесь не означает потерю памяти навсегда; оно описывает необходимость продлить хранение или ограничение доступного доказательства."),
    ("Сводка параметра Go", "Передаваемое между компиляциями описание того, куда могут перейти данные параметра, например в результат или долгоживущее место. Оно помогает анализировать конкретный вызов без полного повторного изучения тела и не является профилем уже выполненных выделений."),
    ("IR компилятора Go", "Промежуточное представление проверенной программы, удобное для последующих преобразований. На разных стадиях оно имеет разные свойства, поэтому исходная строка не обязана соответствовать одному сохраняющемуся узлу."),
    ("Walk Go", "Стадия обработки внутреннего представления, упрощающая высокоуровневые конструкции и организующая необходимые временные значения. Она сохраняет требуемый порядок вычисления, даже когда окончательный код выглядит иначе исходного выражения."),
    ("Раскрытие конструкции", "Перевод сложной языковой операции в более простые действия внутреннего представления. Например, часть операций карт требует runtime-вызовов; такая замена объясняет, почему короткая строка может выполнять несколько низкоуровневых шагов."),
    ("Intrinsic Go", "Операция или функция, для которой компилятор знает специальную реализацию вместо обычного общего вызова. Применимость зависит от архитектуры, версии и условий, поэтому знакомое имя функции не гарантирует одну и ту же инструкцию везде."),
    ("SSA Go", "Промежуточная форма, в которой каждое именованное значение имеет единственное определение, а выполнение описывается графом блоков. Она облегчает доказательство отношений и оптимизацию, но не исполняется процессором как отдельный пользовательский язык."),
    ("Базовый блок SSA", "Последовательность внутренних операций с определённым входом и переходом в конце. Связи блоков описывают возможный поток управления, а их номера являются диагностическими обозначениями и могут меняться между проходами."),
    ("Phi", "Узел выбора SSA-значения по тому, из какого предшествующего блока пришло управление. Он помогает соединять ветви и итерации; наличие узла не означает обязательный отдельный вызов или инструкцию phi в машинном коде."),
    ("Значение памяти SSA", "Внутренний способ выразить зависимости чтений, записей и других эффектов между операциями. Оно не является выделенным приложением объектом, а помогает компилятору не переставить действия с нарушением поведения."),
    ("Доминирование", "Свойство графа, при котором любой путь от входа к выбранному блоку проходит через другой указанный блок. Оно помогает доказать, что нужное условие установлено раньше использования, и не сообщает само по себе частоту прохождения пути."),
    ("Prove Go", "Проход компилятора, использующий известные на путях отношения для упрощения условий и проверок. Он не обязан доказывать произвольную математическую теорему о программе; форма инварианта влияет на доступные ему возможности."),
    ("BCE Go", "Удаление проверки границы, необходимость которой уже исключена доказанными условиями программы. Это сохраняет безопасность доступа, а не отключает её; произвольный индекс без нужных отношений продолжает требовать ошибочного пути."),
    ("CSE Go", "Объединение одинаковых вычислений при доказанно совместимых входах и эффектах. Одинаковый текст двух чтений памяти недостаточен, если между ними данные могли измениться через запись или вызов."),
    ("Удаление мёртвой записи", "Исключение сохранения, результат которого не может повлиять на требуемое поведение. Для доказательства учитываются другие способы доступа к памяти, поэтому отсутствие чтения по тому же исходному имени не является достаточным основанием."),
    ("Lowering Go", "Замена общих операций промежуточного представления машинными формами целевой архитектуры. На этом этапе возможны дополнительные объединения и разложения, поэтому одно общее действие не обязательно становится одной инструкцией."),
    ("Распределение регистров", "Назначение физических регистров и стековых мест внутренним значениям с учётом времени жизни и ограничений инструкций. Одно значение может перемещаться, а один регистр переиспользоваться для разных непересекающихся значений."),
    ("Spill Go", "Сохранение нужного значения в стековом слоте и последующая загрузка, когда регистрового хранения недостаточно или мешает граница вызова. Это не выделение объекта в куче; не каждое обращение к SP является именно spill."),
    ("Живость значения", "Необходимость сохранить значение для возможного последующего использования. Она может закончиться раньше текстовой области переменной и влияет на регистры, стековые сведения и удержание объектов."),
    ("Карта стека Go", "Подготовленные компилятором сведения о местах указателей в определённом состоянии функции. Они позволяют runtime сканировать и обслуживать стек без угадывания по похожим на адрес числами."),
    ("Safe point Go", "Состояние исполнения, в котором runtime располагает необходимыми гарантиями и сведениями для соответствующей служебной операции. Термин не означает отсутствие логических ошибок или гонок данных в прикладном коде."),
    ("ABIInternal", "Внутреннее соглашение вызовов функций Go, определяющее передачу данных и служебное состояние конкретного инструментария. Оно может меняться между версиями и не равно платформенному ABI C."),
    ("ABI0", "Стековое соглашение Go, используемое на определённых границах с ассемблерным кодом. Для взаимодействия с ABIInternal могут создаваться обёртки; его существование не означает, что современный Go передаёт все аргументы только через стек."),
    ("Обёртка ABI", "Сгенерированный переход между соглашениями вызова с перекладкой данных и подготовкой ожидаемого состояния. Успех одной арифметической операции не доказывает корректность самодельной обёртки при GC и росте стека."),
    ("Stack guard Go", "Служебная граница, участвующая в проверке достаточности стека перед исполнением подходящей функции. Она относится к организации стека горутины и не является проверкой длины пользовательского среза."),
    ("Morestack", "Часть пути runtime, связанного с необходимостью расширить стек горутины. Её наличие в коде не означает выполнение при каждом вызове; аргументы и состояние должны сохраниться согласно ABI."),
    ("Контекст замыкания", "Состояние, через которое функциональное значение получает доступ к захваченным данным. Оно отличается от одного адреса инструкции, хотя оптимизация может устранить его явную передачу в конкретном вызове."),
    ("Объектный формат Go", "Внутренний двоичный формат с символами, данными, перемещениями и вспомогательными сведениями для инструментов Go. Он не обязан быть ELF только потому, что окончательный результат предназначен Linux."),
    ("Символ Go linker", "Именованная сущность кода или данных, чьё определение и использования согласуются при связывании. Внутренняя модель включает дополнительные свойства, поэтому разрешение не сводится к простому поиску одинаковой строки."),
    ("Relocation Go", "Описание места инструкции или данных, которое нужно исправить после определения расположения целевого символа. Оно связывает машинное содержимое с размещением и не означает перенос исходного файла в другую директорию."),
    ("Достижимость при связывании", "Возможность попасть к символу от необходимых корней по учитываемым связям. Она определяет, какой код допустимо сохранить или удалить, причём инициализация, интерфейсы и отражение добавляют связи помимо явных вызовов main."),
    ("Linker dead code", "Код, который связыватель может исключить как ненужный для выбранного набора корней и режима. Функция может присутствовать в архиве compile и отсутствовать в executable, поэтому стадии нужно сравнивать отдельно."),
    ("Внутреннее связывание Go", "Режим, в котором Go linker сам выполняет предусмотренное окончательное связывание. Его применимость зависит от цели и входов, а не от одного факта написания основного файла на Go."),
    ("Внешнее связывание Go", "Режим взаимодействия Go linker с системной инструментальной цепочкой для получения окончательного результата. Он требует подходящих внешних компонентов и может иметь другие условия переносимости, чем чистый Go executable."),
    ("Buildmode Go", "Выбранный договор формы результата, например обычное приложение, PIE или библиотека для C. Он меняет требования к экспорту и запуску, а поддержка зависит от платформы и инструментария."),
    ("ELF Go", "Формат окончательного двоичного образа на исследованной Linux-платформе с заголовками и описаниями содержимого. Он отличается от внутреннего пакетного объекта Go и не позволяет по одному имени файла установить все условия запуска."),
    ("PT_LOAD", "Запись программных заголовков ELF, описывающая область загрузки с адресами, размерами и разрешениями. Размер в памяти может отличаться от числа сохранённых байтов, например из-за начально нулевой области."),
    ("PT_INTERP", "Запись ELF с требуемым интерпретатором динамического образа. Его отсутствие на целевой системе способно помешать запуску существующего executable; чистый пример Go в серии такого сегмента не имел."),
    ("Секция ELF", "Логическая часть файла, удобная связывающим и анализирующим инструментам. Она не обязана иметь самостоятельное отображение в память и не тождественна загружаемому сегменту."),
    ("Сегмент ELF", "Область образа, описанная программным заголовком для организации загрузки и других системных задач. Она может включать несколько секций, поэтому подсчёт секций не равен числу отображений процесса."),
    ("DWARF Go", "Отладочные сведения о связи машинных адресов, исходников, типов и размещения значений. Они расширяют возможности анализа, но оптимизированная переменная не обязана иметь простое постоянное место даже при сохранённом DWARF."),
    ("PIE Go", "Позиционно независимый executable, предназначенный для соответствующего механизма перемещаемого размещения. В исследованной сборке он имел тип ELF DYN, но это само по себе не доказывает зависимость от libc или ускорение программы."),
    ("Точка входа ELF", "Адрес начала предусмотренного исполнения образа, указанный в заголовке. Для Go он ведёт к стартовому пути runtime, а не обязательно непосредственно к пользовательской main."),
    ("Span Go", "Группа страниц и объектов, которой управляет внутренний распределитель runtime. Организация span помогает обслуживать классы размеров и сканирование, но её нельзя приравнивать к одному логическому объекту приложения."),
    ("Класс размера Go", "Группа размеров малых объектов, для которой распределитель использует общую организацию свободных мест. Запрос округляется, поэтому изменение логического размера на один байт не всегда меняет реальный расход одинаковым образом."),
    ("Mcache Go", "Локальный для исполнительного ресурса runtime запас span со свободными местами для малых объектов. Он уменьшает синхронизацию в частом пути выделения и не означает отдельный системный запрос для каждого new."),
    ("Mcentral Go", "Уровень распределителя, откуда пополняются наборы span соответствующего класса размера. Получение группы мест позволяет распределить стоимость синхронизации между многими будущими выделениями."),
    ("Mheap Go", "Уровень управления страницами кучи, к которому обращаются при потребности в новых span и крупных объектах. Он связан с получением памяти у системы, но число прикладных выделений не равно числу таких обращений."),
    ("Green Tea GC", "Организация части маркировки и сканирования с накоплением объектов одного span для улучшения локальности. В исходниках Go 1.27.3 она включена по умолчанию; это не обещание одинакового выигрыша для любого графа данных."),
    ("Барьер записи Go", "Дополнительный протокол указательных изменений, необходимый для корректности конкурентной сборки мусора. Компилятор и runtime применяют его по условиям размещения и фазы; не всякая запись числа требует такого же действия."),
    ("Mutator", "Часть исполнения приложения, которая создаёт объекты и меняет ссылки, пока сборщик исследует память. Термин помогает отличить полезную работу и её изменения графа от действий самого GC."),
    ("GC assist", "Участие выделяющего память кода в необходимом прогрессе сборщика. Оно связывает интенсивность создания данных с возможной задержкой операции, но конкретную причину всплеска нужно подтверждать профилем и метриками."),
    ("Живая куча Go", "Объём объектов, которые остаются нужными и достижимыми на выбранной границе наблюдения. Он отличается от накопленного выделенного объёма и не включает автоматически всю рабочую память процесса."),
    ("Поток выделений Go", "Количество создаваемых данных за период или единицу полезной работы. Большой поток может сочетаться с небольшой живой кучей, если объекты короткоживущие, поэтому эти показатели нельзя заменять друг другом."),
    ("GOGC", "Параметр целевого роста, влияющий на частоту и бюджет сборки по правилам runtime. Он задаёт обмен памяти и работы GC, но не делает сохранённый приложением объект недостижимым."),
    ("GOMEMLIMIT", "Мягкое ограничение определённых управляемых runtime ресурсов памяти. Оно не тождественно жёсткому лимиту контейнера и не гарантирует успех при любом живом наборе, cgo-хранении или внешних отображениях."),
    ("PGO Go", "Оптимизация следующей сборки с использованием CPU-профиля представительной работы программы. Она помогает выбирать преобразования, но не разрешает нарушать смысл редко наблюдавшихся путей и не заменяет алгоритмическое исправление."),
    ("Default.pgo", "Предусмотренное имя профильного файла для автоматического обнаружения при сборке main-пакета. Его конкретные байты являются входом результата, поэтому наличие и версию файла нужно учитывать для воспроизводимости."),
    ("CPU-профиль Go", "Выборочные сведения о работе процессора и стеках собственного процесса. Он показывает распределение наблюдавшейся CPU-работы, но не объясняет автоматически всё время сетевого ожидания или отсутствие редких событий."),
    ("Смещение профиля", "Несоответствие записанного распределения работе, для которой выбирается оптимизация. Долгий прогрев или единственный удобный запрос могут получить завышенный вес, даже если сам файл технически корректен."),
    ("Preamble cgo", "Комментарий непосредственно перед import C, используемый как подготовительный C-текст. Его объявления и определения участвуют в генерации мостов и имеют ограничения, особенно при обратном экспорте Go-функций."),
    ("CFLAGS cgo", "Параметры компиляции C-части, задаваемые предусмотренными директивами или окружением. Путь заголовка через -I не заменяет библиотеку при связывании, а скрытые внешние флаги становятся дополнительным входом сборки."),
    ("Pkg-config cgo", "Получение сведений о внешней установленной библиотеке из её описания для подготовки флагов. Это отдельная программа и метаданные, а не менеджер установки Go-модулей; при cross-build нужно выбирать описания целевой среды."),
    ("Sysroot", "Подготовленное корневое окружение заголовков и библиотек целевой системы для инструментальной цепочки. Использование библиотек машины сборки вместо цели способно создать несовместимость, даже если имя исходного пакета одинаково."),
    ("Cross C compiler", "Компилятор C, создающий объекты для другой целевой архитектуры или среды. Изменение GOARCH не превращает обычный локальный GCC в такой инструмент и не обеспечивает нужные заголовки и библиотеки."),
    ("Закреплённая память Go", "Хранение с явно обеспеченным допустимым состоянием закрепления при передаче через предусмотренную границу, например C. Срок закрепления и содержимое ссылок должны удовлетворять правилам; числовой адрес сам по себе не управляет временем жизни."),
    ("Дескриптор cgo", "Управляемая регистрация связи с Go-значением для передачи внешней стороне вместо произвольного сохранения сырого адреса. У неё есть явный жизненный цикл создания, использования и удаления, который не отменяет требования синхронизации."),
    ("Flat и cumulative", "Два представления профильной стоимости: непосредственно внутри функции и вместе с её потомками по вызовам. Высокая накопительная стоимость обработчика не доказывает, что дорогая работа находится именно в его собственном теле."),
]
